                let childPending = try PaymentAudited(entity: child, reason: childReason).teaqlValidateInputGraph()
                if childPending { pending = true }
            } catch let error as CheckException {
                let prefix = ObjectLocation.property("payment_list").index(index)
                throw CheckException(error.violations.map { violation in
                    violation.prefixed(by: prefix)
                })
            }
        }
        for (index, var child) in entity.shipmentList.enumerated() {
            try child.teaqlAttachRoot(entity.teaqlEntityRoot)
            if child.customerOrder != entity.teaqlPreflightID {
                child.updateCustomerOrder(entity.teaqlPreflightID)
            }
            let childReason = child.teaqlEntityRoot.localAuditReason(child.teaqlEntityKey) ?? reason
            do {
                // Evaluate every child, even when the owner already has work.
                let childPending = try ShipmentAudited(entity: child, reason: childReason).teaqlValidateInputGraph()
                if childPending { pending = true }
            } catch let error as CheckException {
                let prefix = ObjectLocation.property("shipment_list").index(index)
                throw CheckException(error.violations.map { violation in
                    violation.prefixed(by: prefix)
                })
            }
        }
        return pending
    }

    func teaqlPreflightGraph(_ context: UserContext) throws {
        if entity.version != 0 && !entity.teaqlEntityRoot.isNew(entity.teaqlEntityKey)
            && entity.teaqlEntityRoot.hasPending(entity.teaqlEntityKey) {
            if !entity.isLoaded("id") {
                throw CheckException([CheckResult(ruleID: "invalid_type", location: .property("id"), message: "Mutation requires a fully loaded entity", entityType: "CustomerOrder")])
